/**
 * createPreamble({ language, labels, kind }) → Typst preamble string.
 *
 * Produces preamble.typ — the named functions Press's /typst builders
 * call into. Currently two functions: #chapter-opener and #section-break.
 *
 * `chapter-opener` is genre-dependent. For the book genre (default) it
 * starts a new page with a large centered chapter title, which is the
 * chapter's level-1 heading: the contents and the running heads find it
 * there, so the section leaves its own H1 out of the body
 * (`utils/chapter-opening.jsx`). `numbered: false` keeps a section that
 * is not a numbered chapter out of the numbering. For the `article` genre
 * it is a no-op: the section's `= H1` that follows it in the body renders
 * as an ordinary section heading (styled by the article template), so
 * sections flow continuously instead of each starting a new page. The
 * "Chapter" overline label is localized via `labels`.
 */
import { resolveLabels } from './labels.js'

export function createPreamble({ language, labels, kind } = {}) {
  const l = resolveLabels({ language, overrides: labels })

  // The article genre wants continuous prose — no per-section page break
  // and no big centered chapter title (the following `= H1` is the
  // heading). Other genres get the page-starting chapter opener.
  const chapterOpener =
    kind === 'article'
      ? String.raw`// ─── Chapter opener (article: no-op — sections flow continuously) ─────────
#let chapter-opener(number: none, title: "", subtitle: "", numbered: true) = []`
      : String.raw`// ─── Chapter opener ──────────────────────────────────────────────────────
#let chapter-opener(number: none, title: "", subtitle: "", numbered: true) = {
  pagebreak(weak: true)
  v(1.5in)
  if number != none {
    align(
      center,
      text(size: 11pt, weight: "regular", fill: luma(90))[
        ${escapeTypstText(l.chapter)} #number
      ],
    )
    v(0.4em)
  }
  if title != "" {
    show heading.where(level: 1): it => align(
      center,
      par(
        justify: false,
        text(size: 20pt, weight: "bold", it.body),
      ),
    )
    if numbered {
      heading(level: 1, title)
    } else {
      heading(level: 1, numbering: none, title)
    }
  }
  if subtitle != "" {
    v(0.4em)
    align(
      center,
      text(size: 13pt, style: "italic", fill: luma(60))[#subtitle],
    )
  }
  v(1.5em)
}`

  return String.raw`// preamble.typ — named functions used by Press/typst section fragments.

// ─── Math (mitex) ────────────────────────────────────────────────────────
// Press's typst adapter emits math as #mitex(\`<latex>\`) wrapped in a
// typst math context (\$…\$ inline / \$ … \$ display). mitex parses
// the LaTeX source and re-emits typst math, sparing us a JS-side
// LaTeX → typst translator. Pin the version explicitly — bump
// deliberately, not with each typst release.
#import "@preview/mitex:0.2.5": mitex

${chapterOpener}

// ─── Section break ───────────────────────────────────────────────────────
#let section-break() = {
  v(1em)
  align(center, text(size: 12pt, "⁂"))
  v(1em)
}
`
}

/**
 * Escape characters that have special meaning inside Typst content mode.
 * Labels come from site.yml / LABELS_BY_LANGUAGE and are text, not markup,
 * so `#`, `*`, `_`, `[`, `]`, `\` should not be interpreted as syntax.
 */
function escapeTypstText(s) {
  return String(s).replace(/[\\#\*_\[\]]/g, (c) => '\\' + c)
}
